#ifndef MOD_STORY_PRESENTATION_H
#define MOD_STORY_PRESENTATION_H
#include "mod_story.h"
/* Original summaries authored for this campaign; presentation resources vary by saga.
   Stable IDs keep recap text attached to its chapter when future sagas are appended. */
typedef struct StPreludeText {const char *id,*body[2];} StPreludeText;
static const StPreludeText stPreludeTexts[]={
 {"saiyan_01_raditz_wasteland",{"Years of peace have passed since Goku's last great adventure. Far from the celebrations, Piccolo continues his training, determined to surpass his rival.\n\nBut an unfamiliar presence has just reached Earth. The stranger knows far more about this world than he should... and his power is unlike anything Piccolo has faced.","Han pasado a\303\261os de paz desde la \303\272ltima gran aventura de Goku. Lejos de las celebraciones, Piccoro contin\303\272a su entrenamiento, decidido a superar a su rival.\n\nPero una presencia desconocida acaba de llegar a la Tierra. El reci\303\251n llegado sabe demasiado sobre este mundo... y su poder no se parece a nada que Piccoro haya enfrentado."}},
 {"saiyan_02_kame_house",{"Goku visits his friends at Kame House, bringing his young son Gohan along. What should have been a happy reunion is interrupted by an unexpected visitor.\n\nCalling Goku by another name, the stranger reveals a connection to a forgotten past. Krillin steps forward, but the peaceful island is about to become the scene of a terrible confrontation.","Goku visita a sus amigos en Kame House y lleva consigo a su peque\303\261o hijo, Gohan. Lo que deb\303\255a ser un alegre reencuentro se interrumpe con la llegada de un visitante inesperado.\n\nEl desconocido llama a Goku por otro nombre y revela un v\303\255nculo con un pasado olvidado. Krilin intenta detenerlo, pero la tranquila isla est\303\241 a punto de convertirse en el escenario de un terrible enfrentamiento."}},
 {"saiyan_03_unlikely_alliance",{"Raditz has taken Gohan and delivered an impossible demand to Goku. Saving the boy will mean facing an enemy far stronger than either of Earth's greatest rivals.\n\nPiccolo offers an unexpected alliance. Setting their differences aside, Goku and Piccolo head toward Raditz, unaware that the battle may demand a sacrifice neither of them can escape.","Raditz se ha llevado a Gohan y le ha impuesto a Goku una exigencia imposible. Rescatar al ni\303\261o significa enfrentarse a un enemigo mucho m\303\241s poderoso que los dos grandes rivales de la Tierra.\n\nPiccoro propone una alianza inesperada. Dejando atr\303\241s sus diferencias, ambos parten hacia Raditz, sin imaginar el sacrificio que podr\303\255a exigirles esta batalla."}},
 {"saiyan_04_gohans_power",{"The victory over Raditz has cost Goku his life, and even stronger Saiyans are already on their way. Piccolo takes Gohan into the wilderness, hoping to awaken the power he witnessed during the battle.\n\nUnder the light of the full moon, the frightened child undergoes a terrifying change. Piccolo must stop the rampage before Gohan destroys everything around him.","La victoria sobre Raditz le ha costado la vida a Goku, y otros Saiyajin a\303\272n m\303\241s fuertes ya vienen en camino. Piccoro lleva a Gohan a un lugar apartado para despertar el poder que mostr\303\263 durante la batalla.\n\nBajo la luz de la luna llena, el ni\303\261o sufre una transformaci\303\263n aterradora. Piccoro tendr\303\241 que detenerlo antes de que su furia destruya todo a su alrededor."}},
 {"saiyan_05_one_year",{"One year is all Earth has left to prepare. While Goku follows a perilous road through the Other World, Gohan must learn to survive without his father's protection.\n\nPiccolo's training offers little comfort, but every hard lesson brings the boy closer to becoming a fighter. Far away, Goku searches for a master who can teach him to face the coming threat.","La Tierra solo tiene un a\303\261o para prepararse. Mientras Goku recorre un peligroso camino en el otro mundo, Gohan debe aprender a sobrevivir sin la protecci\303\263n de su padre.\n\nEl entrenamiento de Piccoro no da tregua, pero cada lecci\303\263n acerca al ni\303\261o a convertirse en un guerrero. Muy lejos de all\303\255, Goku busca a un maestro capaz de prepararlo para la amenaza que se aproxima."}},
 {"saiyan_06_lookout",{"Earth's defenders gather at Kami's Lookout. With Goku still far away, Krillin, Yamcha, Tien and Chiaotzu must push beyond their old limits.\n\nGuided by Mr. Popo, they face a trial that turns their own strength against them. The coming battle will leave no room for hesitation, and training alone may not be enough.","Los defensores de la Tierra se re\303\272nen en el palacio de Kami. Con Goku todav\303\255a lejos, Krilin, Yamcha, Ten Shin Han y Chaoz deben superar sus propios l\303\255mites.\n\nBajo la gu\303\255a de Mr. Popo, afrontan una prueba que vuelve su propia fuerza contra ellos. La batalla que se aproxima no dejar\303\241 lugar para las dudas... y quiz\303\241 ni siquiera todo este entrenamiento sea suficiente."}},
 {"saiyan_07_saiyans_arrive",{"The year of preparation is over. Two Saiyan space pods cross the sky, leaving destruction in their wake. Goku has not returned.\n\nThe defenders of Earth assemble to confront Vegeta and Nappa. Before the invaders reveal their own strength, a smaller enemy rises from the soil to test the warriors who stand in their way.","El a\303\261o de preparaci\303\263n ha terminado. Dos naves Saiyajin cruzan el cielo y dejan destrucci\303\263n a su paso. Goku a\303\272n no ha regresado.\n\nLos defensores de la Tierra se re\303\272nen para enfrentar a Vegeta y Nappa. Antes de mostrar su propia fuerza, los invasores hacen surgir de la tierra a un enemigo que pondr\303\241 a prueba a quienes se atreven a detenerlos."}},
 {"saiyan_08_six_seeds",{"The first exchange has shown that Earth's warriors are no longer the fighters they once were. Yamcha steps forward, confident that their training has prepared them for the Saibamen.\n\nBut these creatures know no fear and fight without mercy. A moment of confidence may carry a price far greater than anyone expects.","El primer enfrentamiento ha demostrado cu\303\241nto han crecido los guerreros de la Tierra. Yamcha se adelanta, convencido de que su entrenamiento lo ha preparado para enfrentar a los Saibaman.\n\nPero estas criaturas no conocen el miedo y combaten sin piedad. Un instante de confianza puede tener un precio mucho mayor de lo que todos imaginan."}},
 {"saiyan_09_nappa",{"The Saibamen have been defeated, but Yamcha will not stand beside his friends again. Now Nappa steps onto the battlefield.\n\nHis overwhelming strength threatens to break the defenders before Goku can arrive. Faced with an enemy beyond anything they imagined, Tien and Chiaotzu prepare to give everything they have.","Los Saibaman han sido derrotados, pero Yamcha ya no volver\303\241 a levantarse junto a sus amigos. Ahora Nappa entra en la batalla.\n\nSu fuerza amenaza con destruir a los defensores antes de que llegue Goku. Frente a un enemigo que supera todo lo que hab\303\255an imaginado, Ten Shin Han y Chaoz se preparan para darlo todo."}},
 {"saiyan_10_three_hours",{"Vegeta grants the exhausted defenders three hours to wait for Kakarot. The silence offers little hope, and each passing moment makes the losses harder to bear.\n\nWhen the waiting ends, Piccolo, Krillin and Gohan must face Nappa once more. Protecting the Earth now means protecting one another, no matter the cost.","Vegeta concede a los agotados defensores tres horas para esperar a Kakarot. El silencio apenas trae esperanza, y cada minuto hace m\303\241s dolorosas las p\303\251rdidas.\n\nCuando termina la espera, Piccoro, Krilin y Gohan deben enfrentar de nuevo a Nappa. Proteger la Tierra significa ahora protegerse entre ellos, cueste lo que cueste."}},
 {"saiyan_11_goku_returns",{"Goku finally returns, but several familiar voices have already fallen silent. Gohan and Krillin can barely hold on against Nappa.\n\nAfter his training with King Kai, Goku carries a new strength and new techniques. Before confronting Vegeta, he must reach his friends and stop the warrior who has devastated their ranks.","Goku por fin regresa, pero varias voces conocidas ya se han apagado. Gohan y Krilin apenas resisten frente a Nappa.\n\nTras su entrenamiento con Kaio, Goku vuelve con una nueva fuerza y nuevas t\303\251cnicas. Antes de enfrentar a Vegeta, tendr\303\241 que llegar hasta sus amigos y detener al guerrero que ha destrozado sus filas."}},
 {"saiyan_12_kaioken",{"Nappa is no longer the greatest danger on the battlefield. Vegeta now faces the low-class Saiyan whose strength has defied every expectation.\n\nGoku must push King Kai's teachings further than ever before. As the battle intensifies, protecting the Earth may demand more power than his own body can endure.","Nappa ya no es el mayor peligro del campo de batalla. Vegeta enfrenta ahora al Saiyajin de clase baja cuya fuerza ha superado todas sus expectativas.\n\nGoku tendr\303\241 que llevar las ense\303\261anzas de Kaio m\303\241s lejos que nunca. A medida que crece la intensidad del combate, proteger la Tierra podr\303\255a exigir m\303\241s poder del que su cuerpo es capaz de soportar."}},
 {"saiyan_13_artificial_moon",{"Goku has forced Vegeta to acknowledge his strength, but the Saiyan prince refuses to accept defeat. A strange sphere of light rises above the battlefield.\n\nWith the power of an artificial moon, Vegeta reveals the terrifying form hidden within his people. Exhausted and injured, Goku must find another way to stop a giant.","Goku ha obligado a Vegeta a reconocer su fuerza, pero el pr\303\255ncipe Saiyajin se niega a aceptar la derrota. Una extra\303\261a esfera de luz se eleva sobre el campo de batalla.\n\nGracias a una luna artificial, Vegeta revela la terrible forma que esconde su raza. Agotado y herido, Goku tendr\303\241 que encontrar otra manera de detener a un gigante."}},
 {"saiyan_14_yajirobe",{"The Great Ape's strength has left Goku helpless. Gohan and Krillin return to a battlefield where every direct attack seems hopeless.\n\nYet the giant has a weakness. Hidden nearby, an unlikely ally waits for a chance to act. A single opening may be all they need to turn the battle around.","La fuerza del Gran Mono ha dejado a Goku indefenso. Gohan y Krilin regresan a un campo de batalla donde cualquier ataque directo parece in\303\272til.\n\nSin embargo, el gigante tiene una debilidad. Oculto entre las rocas, un aliado inesperado espera su oportunidad. Quiz\303\241 baste una sola distracci\303\263n para cambiar el rumbo de la batalla."}},
 {"saiyan_15_last_energy",{"Vegeta has lost his giant form, but the battle is far from over. Goku can no longer fight, and his friends are running out of strength.\n\nOne last hope remains: the energy gathered for a technique that never reached its target. Trusting Krillin with that power, Goku places the future of the Earth in his friends' hands.","Vegeta ha perdido su forma de gigante, pero la batalla est\303\241 lejos de terminar. Goku ya no puede luchar y sus amigos se est\303\241n quedando sin fuerzas.\n\nA\303\272n queda una esperanza: la energ\303\255a reunida para una t\303\251cnica que nunca alcanz\303\263 su objetivo. Al confiarle ese poder a Krilin, Goku pone el futuro de la Tierra en manos de sus amigos."}},
 {"saiyan_16_last_giant",{"Even the last desperate attack has not ended Vegeta's resistance. Wounded warriors struggle to stand while the artificial moon still shines above them.\n\nGohan's hidden power is about to change the battle once again. This time, the defenders must survive a giant of their own... and guide his fury toward their enemy.","Ni siquiera el \303\272ltimo ataque desesperado ha acabado con la resistencia de Vegeta. Los guerreros heridos intentan mantenerse en pie mientras la luna artificial sigue brillando.\n\nEl poder oculto de Gohan est\303\241 a punto de cambiar la batalla una vez m\303\241s. Esta vez tendr\303\241n que sobrevivir a su propio gigante... y dirigir su furia hacia el enemigo."}},
 {"saiyan_17_let_him_live",{"The battle has finally reached its end. The Earth survives, but its defenders have paid a terrible price, and Vegeta is still within reach of a final blow.\n\nAs anger gives way to an unexpected plea for mercy, another hope begins to take shape. Beyond the ruined battlefield lies a distant world... and perhaps a way to bring their friends back.","La batalla por fin ha llegado a su fin. La Tierra sobrevive, pero sus defensores han pagado un precio terrible y Vegeta a\303\272n est\303\241 al alcance de un \303\272ltimo golpe.\n\nMientras la ira se enfrenta a una inesperada petici\303\263n de clemencia, empieza a surgir otra esperanza. M\303\241s all\303\241 del campo de batalla destruido existe un mundo lejano... y quiz\303\241 una forma de recuperar a sus amigos."}},
};
static const char*STP_Text(int chapter,int language){unsigned i;if(chapter<0||chapter>=ST_COUNT)return "";for(i=0;i<sizeof(stPreludeTexts)/sizeof(stPreludeTexts[0]);i++)if(!strcmp(stPreludeTexts[i].id,stChapters[chapter].id))return stPreludeTexts[i].body[language==1];return stChapters[chapter].recap[language==1];}
/* Classic Z: Saiyan/Freezer/Cell. Buu, movies, GT, DB and What-if each have their own resource slot. */
static int STP_Profile(int saga){return saga==0||saga==1?0:saga>=2&&saga<8?saga:0;}
static int STP_RecapMs(int chapter){int n=0;const char *text=STP_Text(chapter,0);while(text[n])n++;int ms=12000+n*35;return ms<22000?22000:ms>38000?38000:ms;}
static int STP_TitleMs(int saga){return saga==3?10300:saga==5?8750:saga==2?9490:8900;}
#endif
